use serde_json::{Value, Error};

pub fn solve(input: Value) -> Value {
    if let Value::String(s) = input {
        if let Ok(num) = s.parse::<f64>() {
            if num.abs() <= 1_000_000.0 {
                return Value::Number((num * 100.0).round().into());
            }
        }
    }
    Value::Null
}
